   "Pay evidence: junior Toulouse 34-38k (Fed IT 2025, via pstb.fr); TPC 2026 regional medians including variable pay 36k, 42k, 47.5k; Free-Work other cities 36.0k, 45.9k, 51.9k. None of these split out Toulouse, so they are regional proxies, and the figures here sit between those proxies and the posted ads.",
   "Posted ranges on HelloWork: Adentis 35-40k, Mutuelle Viasante 37-47k, Step Up 38-48k, Kaizen C#/React 40-48k, Klanik 42-52k, Ippon 40-55k, MyUnisoft Ruby/React 50-55k, Le Comptoir des Pharmacies 52-58k. Welcome to the Jungle: Hinfact senior 48-55k, JurIA 45-60k, OpenAirlines confirmed from 43k, Roundtable senior 75-85k and lead 80-90k. The Roundtable ads are far above the rest and they were treated as outliers.",
   "Impatriate regime: a new graduate hired directly from abroad, not French tax resident in the previous five calendar years, can exempt 30% of pay for up to 8 years (a rough estimate: up to about 175 EUR a month at mid level, not in the table). Anyone who was a French tax resident in any of those five years does not qualify.",
   "Cheaper nearby towns: Colomiers 2-room asking rent averages 683 against 743 in Toulouse (123 Loger, March 2026), a saving of about 60 EUR a month.",
